scwin.trigger1_onclick = function() {
    var tabNm = "iframe",
        tabKey = "test_" + scwin.guid++;
    var tabOptions = {
        label: tabNm,
        closable: true,
        openAction: "select"
    };
    var contentsOptions = {
        frameMode: "iframe",
        src: "wframe_spaInitCount_WPFF-138_(WSQ-3302)_sub.xml"
    };
    var ret = tabControl1.addTab(tabKey, tabOptions, contentsOptions);
    //선택한 tab 활성화.
    if (ret) {
        tabControl1.setSelectedTabIndex(tabControl1.getTabIndex(tabKey));
    }
};
scwin.trigger2_onclick = function() {
    scwin.guid++;
    var tabNm = "wframe",
        tabKey = "test_" + scwin.guid;
    var tabOptions = {
        label: tabNm,
        closable: true,
        openAction: "select"
    };
    var contentsOptions = {
        wframe: true,
        frameMode: "wframe",
        src: "wframe_spaInitCount_WPFF-138_(WSQ-3302)_sub.xml",
        scope: true
    };
    var ret = tabControl1.addTab(tabKey, tabOptions, contentsOptions);
    //선택한 tab 활성화.
    if (ret) {
        tabControl1.setSelectedTabIndex(tabControl1.getTabIndex(tabKey));
    }
};
scwin.trigger3_onclick = function() {
    var tabNm = "wframePreload",
        tabKey = "test_" + scwin.guid++;
    var tabOptions = {
        label: tabNm,
        closable: true,
        openAction: "select"
    };
    var contentsOptions = {
        //wframe : true,
        frameMode: "wframePreload",
        src: "wframe_spaInitCount_WPFF-138_(WSQ-3302)_sub.xml",
        scope: true
    };
    var ret = tabControl1.addTab(tabKey, tabOptions, contentsOptions);
    //선택한 tab 활성화.
    if (ret) {
        tabControl1.setSelectedTabIndex(tabControl1.getTabIndex(tabKey));
    }
};
scwin.checkVal = function() {
    var temp = WebSquare.wUnit.getDomById($p.id + 'tabControl1_contents_test_1_body').className.includes('w2wframe');
    return temp;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 개발자도구를 열고 main샘플 실행 후 'addTab(wframe)' 버튼 클릭 후 inspect를 확인하고 class로 시작하는 파일이 wframe로 보여지는지 확인한다.(이전에는 iframe로 보여짐)
    //1. Open the developer tool, run the main sample, check the inspect after clicking the 'addTab (wframe)' button, and check that the file starting with class is shown as wframe (previously shown as iframe)
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 1. id='tabControl1_contents_test_1_body'의class='w2wframe w2tabContainer_contents w2tabcontrol_contents_wrapper'
    //1. id='tabControl1_contents_test_1_body'의class='w2wframe w2tabContainer_contents w2tabcontrol_contents_wrapper'
    //WebSquare.wUnit.addCommand("assert","WebSquare.wUnit.getDomById($p.id+'tabControl1_contents_test_1_body').className == 'w2wframe w2tabContainer_contents w2tabcontrol_contents_wrapper'", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    //Test step 2. 'addTab(wframePreload)' 버튼 클릭 후 inspect를 확인하고 class로 시작하는 파일이 wframe로 보여지는지 확인한다.(이전에는 iframe로 보여짐)
    //2. Click on the 'addTab (wframePreload)' button to check inspect and check that the file starting with class is visible as a wframe (previously shown as iframe)
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 2. id='tabControl1_contents_test_2_body'의class='w2wframe w2tabContainer_contents w2tabcontrol_contents_wrapper'
    //2. id='tabControl1_contents_test_2_body'의class='w2wframe w2tabContainer_contents w2tabcontrol_contents_wrapper'
    //WebSquare.wUnit.addCommand("assert","WebSquare.wUnit.getDomById($p.id+'tabControl1_contents_test_1_body').className == 'w2wframe w2tabContainer_contents w2tabcontrol_contents_wrapper'", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.guid = 0;
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 20-Mar-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
